// Meta webhook dogrulama. Anahtar uretim aninda gomuldu (bkz. uretici).
const DOGRULAMA_ANAHTARI = "<REDAKTE:MESSENGER_VERIFY_TOKEN>";

const q = $input.first().json.query || {};
const mod  = q['hub.mode'];
const tok  = q['hub.verify_token'];
const chal = q['hub.challenge'];

if (mod === 'subscribe' && tok === DOGRULAMA_ANAHTARI) {
  // Meta sadece challenge degerini duz metin bekler
  return [{ json: { dogrulandi: true, cevap: String(chal ?? '') } }];
}
return [{ json: { dogrulandi: false, cevap: 'dogrulama basarisiz' } }];

// =============================================================================
// L'CARLIE - TRAFIK SINIFLANDIRMA (test / production / unknown)
//
// CR-002.5 madde A · 15.09.2026
//
// Bu dosya n8n dugumlerine AYNEN GOMULUR (build-*-workflow.js tarafindan
// /tmp/kimlik.js olarak okunur). n8n Code node'unda require() yoktur;
// module.exports en altta ve korumali - build betikleri onu kirpar.
//
// 🔴 NEDEN VAR:
//    CR-002'de sinifllandirma bir REGEX RED LISTESI ile yapiliyordu
//    (TEST_KIMLIK_DESENI). Red listeleri her zaman GERIDEN GELIR: 15.09
//    23:37'de paralel bir oturum 'sinav-0-30197' kimlikleriyle 12 test
//    mesaji gonderdi, desende 'sinav' olmadigi icin hepsi URETIM
//    KONUSMASI sayildi ve panel bekleyen musteriyi 3 yerine 5 gosterdi.
//    Yeni bir test adi bulan herkes gostergeyi kirletebiliyordu.
//
//    Yeni kural: TEST TRAFIGI KENDINI BEYAN ETMEK ZORUNDA.
//    Zorunlu onek: 'test-'
//
// 🔴 UC SINIF - 'unknown' OTOMATIK URETIM SAYILMAZ:
//    production : gercek musteri trafigi
//    test       : sentetik / fixture / smoke / sinav / dogrulama
//    unknown    : kimlik yok veya atfedilemiyor  -> METRIGE GIRMEZ,
//                 ama KAYBEDILMEZ, ayri raporlanir
// =============================================================================

const TEST_ONEK = 'test-';

// -----------------------------------------------------------------------------
// trafikSinifi(musteriId, acikSinif)
//
// Oncelik sirasi (CR-002.5 madde A):
//   a) ACIK BEYAN  - yalnizca GUVENILIR cagiranlar verir (fixture, harness)
//   b) 'test-' ONEKI
//   c) kimliksiz   -> unknown
//   d) digerleri   -> production
//
// 🔴 ACIK BEYAN WEBHOOK GOVDESINDEN OKUNMAZ.
//    Instagram webhook'unun govdesi tamamen istemci kontrolunde. Eger
//    govdedeki 'is_test' alanina guvenseydik, herkes kendi mesajini
//    "test" isaretleyip panelden GIZLEYEBILIRDI - insana aktarilan
//    gercek bir konusma gorunmez olurdu. Kanal kodu bu yuzden acik
//    beyani HIC gecirmez; yalnizca onek belirleyicidir.
//    Acik beyan, kodun kendi ic testleri/fixture'lari icindir.
//
// 🔴 ESKI REGEX BURADA YOK. Tarihsel kayitlar icin geriye donuk uyum
//    yalnizca saglik.sh tarafinda, SON CARE olarak uygulanir.
// -----------------------------------------------------------------------------
function trafikSinifi(musteriId, acikSinif) {
  if (acikSinif === 'test' || acikSinif === true)  return 'test';
  if (acikSinif === 'production')                  return 'production';

  const id = String(musteriId == null ? '' : musteriId).trim();
  if (!id || id === '-')                           return 'unknown';
  // 🔴 toLowerCase() Turkce yerel ayarda 'I' -> 'ı' yapabilir; onek ASCII
  //    oldugu icin karsilastirma da ASCII kucuk harfle yapilir.
  if (id.slice(0, TEST_ONEK.length).toLowerCase() === TEST_ONEK) return 'test';
  return 'production';
}

// -----------------------------------------------------------------------------
// testKimligiUret(ad) - fixture/test kimligi uretici
//
// Yeni bir fixture yazan herkesin dogru oneki elle hatirlamasini beklemeyiz;
// uretici zaten dogrusunu verir (CR-002.5 madde A-4).
//   testKimligiUret('smoke')     -> 'test-smoke-m3kq8p7f'
//   testKimligiUret('test-x')    -> 'test-x-m3kq8p7f'   (cift onek eklenmez)
// -----------------------------------------------------------------------------
function testKimligiUret(ad) {
  let temiz = String(ad == null ? 'fixture' : ad).trim().replace(/[^A-Za-z0-9_-]/g, '-');
  if (!temiz) temiz = 'fixture';
  if (temiz.slice(0, TEST_ONEK.length).toLowerCase() === TEST_ONEK) {
    temiz = temiz.slice(TEST_ONEK.length);
  }
  const r = Date.now().toString(36) + Math.random().toString(36).slice(2, 6);
  return TEST_ONEK + temiz + '-' + r;
}

function testKimligiMi(id) {
  return trafikSinifi(id) === 'test';
}

// -----------------------------------------------------------------------------
// kimlikDogrula(id) - test harness kapisi (CR-002.5 madde A-3)
//
// 🔴 CANLI UC NOKTAYA istek gonderen her test bunu cagirmali.
//    Onek yoksa TEST CALISMAZ - sessizce uretim metrigini kirletmek
//    yerine gurultulu bicimde durur.
// -----------------------------------------------------------------------------
function kimlikDogrula(id, nerede) {
  const s = trafikSinifi(id);
  if (s !== 'test') {
    throw new Error(
      'TEST KIMLIK STANDARDI IHLALI' + (nerede ? ' (' + nerede + ')' : '') +
      ': "' + id + '" kimligi "' + TEST_ONEK + '" ile baslamiyor. ' +
      'Sentetik trafik uretim metrigine giremez - testKimligiUret() kullanin.'
    );
  }
  return id;
}

// =============================================================================
// L'CARLIE - ORTAK HATA KAYDI YARDIMCILARI
//
// CR-002 madde 2 · 15.09.2026
//
// Bu dosya bir n8n dugumune AYNEN GOMULUR (build-*-workflow.js tarafindan
// /tmp/hata-kaydi.js olarak okunur ve kodun basina yapistirilir).
// n8n Code node'unda require() yoktur; bu yuzden module.exports en altta
// ve korumali - build betikleri onu kirpar.
//
// 🔴 NEDEN VAR:
//    CR-001'de aktif Instagram ve WhatsApp workflow'larinda HICBIR hata
//    yolu olmadigi bulundu. Ajan bir istisna firlattiginda musteri HTTP 500
//    aliyor; kayit yazilmiyor, eskalasyon olusmuyor, sayac artmiyor -
//    mesaj IZSIZ kayboluyordu. Bu yardimcilar, her kanalda AYNI sekilde
//    calisan tek bir hata kaydi bicimi saglar.
//
// 🔴 PII YASAGI:
//    Hata kaydina musteri mesaji, telefon, e-posta YAZILMAZ.
//    Kimlik yerine 'correlation_id' tutulur; gercek musteri kimligi zaten
//    eskalasyon/kayit listelerinde var. Hata kaydi operasyonel bir kayittir,
//    konusma kaydi degildir.
// =============================================================================

// Kac hata kaydi saklanacak. Statik veri her calistirmada TAMAMEN yeniden
// yazildigi icin bu liste sinirsiz buyuyemez.
const HATA_KAYIT_SINIRI = 200;

// -----------------------------------------------------------------------------
// PII temizleme
//
// 🔴 Hata metinleri bazen girdiyi yankilar (ornegin JSON ayristirma hatalari
//    "unexpected token ... at position" ile birlikte govdeyi basabilir).
//    Bu yuzden ozet kaydedilmeden ONCE temizlenir, sonra kirpilir.
// -----------------------------------------------------------------------------
function piiTemizle(metin) {
  let t = String(metin == null ? '' : metin);
  // e-posta
  t = t.replace(/[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/g, '<eposta>');
  // 6+ haneli rakam dizileri (telefon, wamid, sipariş no, kart benzeri)
  t = t.replace(/\d{6,}/g, '<sayi>');
  // Meta mesaj kimlikleri (wamid.*) - rakamsiz da olabiliyor
  t = t.replace(/wamid\.[A-Za-z0-9_=-]+/gi, '<mesajId>');
  // Uzun base64/token benzeri diziler
  t = t.replace(/\b[A-Za-z0-9_-]{32,}\b/g, '<uzun-deger>');
  // Satir sonlarini tek satira indir
  t = t.replace(/\s+/g, ' ').trim();
  return t.slice(0, 200);
}

// -----------------------------------------------------------------------------
// Hata sinifi
//
// 'continueRegularOutput' ile gelen oge farkli bicimlerde olabilir:
//   { error: 'metin' } · { error: { name, message } } · { error: { message } }
// Hangisi gelirse gelsin kararli bir sinif adi uretilir.
// -----------------------------------------------------------------------------
function hataSinifi(hata) {
  if (!hata) return 'BILINMEYEN';
  if (typeof hata === 'string') {
    if (/not found|bulunamad/i.test(hata))            return 'ALT_AKIS_BULUNAMADI';
    if (/active version|not active|yayinda degil/i.test(hata)) return 'ALT_AKIS_YAYINDA_DEGIL';
    if (/timeout|zaman asimi/i.test(hata))            return 'ZAMAN_ASIMI';
    if (/birden fazla|multiple items/i.test(hata))    return 'COKLU_OGE';
    return 'CALISMA_HATASI';
  }
  const ad = hata.name || hata.errorName || '';
  const mesaj = hata.message || hata.description || '';
  if (ad) return String(ad).replace(/[^A-Za-z0-9_]/g, '_').slice(0, 40).toUpperCase();
  return hataSinifi(String(mesaj || 'BILINMEYEN'));
}

function hataOzeti(hata) {
  if (!hata) return '';
  if (typeof hata === 'string') return piiTemizle(hata);
  return piiTemizle(hata.message || hata.description || JSON.stringify(hata));
}

// -----------------------------------------------------------------------------
// Korelasyon kimligi
//
// 🔴 PII ICERMEZ. Musteri kimliginden TUREMEZ - yoksa telefon numarasi
//    dolayli olarak hata kaydina sizardi.
//    Bicim: <kanal>-<zaman36>-<rastgele4>   ornek: ig-m3kq8p-7f2a
// -----------------------------------------------------------------------------
function korelasyonUret(kanal) {
  const k = String(kanal || 'x').slice(0, 4);
  const z = Date.now().toString(36);
  const r = Math.random().toString(36).slice(2, 6);
  return k + '-' + z + '-' + r;
}

// -----------------------------------------------------------------------------
// Hata kaydi yaz
//
// Zorunlu alanlar (CR-002 madde 2):
//   timestamp · workflow_id · execution_id · channel · stage
//   error_class · error_summary · correlation_id
// -----------------------------------------------------------------------------
function hataKaydet(sd, a) {
  if (!sd) return null;
  if (!Array.isArray(sd.hatalar)) sd.hatalar = [];
  const kayit = {
    ts: new Date().toISOString(),
    workflow_id: String(a.workflow_id || '-'),
    execution_id: String(a.execution_id || '-'),
    channel: String(a.channel || '-'),
    stage: String(a.stage || '-'),
    error_class: String(a.error_class || 'BILINMEYEN').slice(0, 60),
    error_summary: piiTemizle(a.error_summary || ''),
    correlation_id: String(a.correlation_id || '-')
  };
  sd.hatalar.unshift(kayit);
  if (sd.hatalar.length > HATA_KAYIT_SINIRI) sd.hatalar.length = HATA_KAYIT_SINIRI;
  sd.hataToplam = (sd.hataToplam || 0) + 1;
  return kayit;
}

// n8n'e gomulurken bu blok build betigi tarafindan kirpilir.

// ===== n8n: Meta Messenger payload'ini ayikla =====

// 🔴 HIZ SINIRI
//
// ⚠️ IP SINIRI YOK - BILEREK. Tum istekler Meta'nin birkac IP'sinden
//    gelir; IP'ye sinir koymak reklam donen bir gunde GERCEK musterileri
//    bogar. Kimlik, Meta'nin verdigi gonderen kimligidir (PSID).
const KISI_LIMIT = 20, KISI_PENCERE = 10 * 60 * 1000;
const TOPLAM_LIMIT = 1000, TOPLAM_PENCERE = 60 * 60 * 1000;

// 🔴 24 SAAT PENCERESI (Messenger standart mesajlasma penceresi).
const PENCERE_MS = 24 * 60 * 60 * 1000;

const sd = $getWorkflowStaticData('global');
if (!Array.isArray(sd.islenenMesajlar)) sd.islenenMesajlar = [];
sd.hiz = sd.hiz || {};
sd.toplam = Array.isArray(sd.toplam) ? sd.toplam : [];

const simdi = Date.now();
sd.toplam = sd.toplam.filter(t => simdi - t < TOPLAM_PENCERE);
for (const k of Object.keys(sd.hiz)) {
  sd.hiz[k] = sd.hiz[k].filter(t => simdi - t < KISI_PENCERE);
  if (!sd.hiz[k].length) delete sd.hiz[k];
}

const cikti = [];
let elenen = { echo: 0, tekrar: 0, olayDegil: 0, hiz: 0 };

// 🔴 all() - first() DEGIL. first() kullanilirsa diger musterilerin
//    mesajlari HATA VERMEDEN duser. Bu projede uc kez yasandi.
for (const item of $input.all()) {
  const govde = item.json.body ?? item.json;

  // Messenger zarfi: entry[].messaging[]  (WhatsApp'taki changes[] DEGIL)
  for (const giris of (govde.entry ?? [])) {
    const sayfaId = String(giris.id ?? '');

    for (const olay of (giris.messaging ?? [])) {
      const m = olay.message;

      // 🔴 YALNIZ MESAJ OLAYLARI. delivery/read/reaction/postback/
      //    message_edit mesaj DEGILDIR; ajana verilirse anlamsiz cevap
      //    uretir ve pilot kaydini kirletir.
      if (!m) { elenen.olayDegil++; continue; }

      const gonderen = String(olay.sender?.id ?? '');
      const alici    = String(olay.recipient?.id ?? '');

      // 🔴 ECHO KAPISI - IKI KAT.
      //    (a) Meta kendi gonderdigimiz mesaji is_echo=true ile geri bildirir.
      //    (b) Ayrica gonderen sayfanin kendisi olabilir.
      //    Elenmezse: cevap -> echo -> cevap -> ... sonsuz dongu. Meta bunu
      //    spam sayar. Bu dosyada ban riskinin en somut kaynagi budur.
      if (m.is_echo === true || (sayfaId && gonderen === sayfaId) || gonderen === alici) {
        elenen.echo++;
        continue;
      }

      // Tekrar gonderim korumasi (idempotency): Meta 200 alamazsa ayni
      // mesaji yeniden gonderir; musteri ayni cevabi iki kez almamali.
      const mid = m.mid ? String(m.mid) : '';
      if (mid && sd.islenenMesajlar.indexOf(mid) !== -1) { elenen.tekrar++; continue; }
      if (mid) {
        sd.islenenMesajlar.unshift(mid);
        if (sd.islenenMesajlar.length > 2000) sd.islenenMesajlar.length = 2000;
      }

      if (sd.hiz[gonderen] && sd.hiz[gonderen].length >= KISI_LIMIT) { elenen.hiz++; continue; }
      if (sd.toplam.length >= TOPLAM_LIMIT) { elenen.hiz++; continue; }
      sd.hiz[gonderen] = sd.hiz[gonderen] || [];
      sd.hiz[gonderen].push(simdi);
      sd.toplam.push(simdi);

      // Sadece metin mesajlarini isle. Gorsel/ses/konum/dosya insana gider.
      const metin = (typeof m.text === 'string' && m.text.trim())
        ? m.text.trim()
        : (m.quick_reply?.payload ? String(m.quick_reply.payload) : null);

      const ekTipi = Array.isArray(m.attachments) && m.attachments.length
        ? String(m.attachments[0].type || 'ek')
        : null;

      // 🔴 24 SAAT PENCERESI. olay.timestamp musterinin mesaj anidir;
      //    pencere ONDAN baslar. Damga okunamazsa pencere ACIK SAYILMAZ --
      //    bilinmeyeni "gonderilebilir" kabul etmek tam olarak ban uretir.
      const damga = Number(olay.timestamp);
      const damgaGecerli = Number.isFinite(damga) && damga > 0;
      const pencereIcinde = damgaGecerli ? (simdi - damga) < PENCERE_MS : false;

      cikti.push({
        json: {
          mesaj: metin ?? '',
          musteriId: gonderen,
          musteriAdi: null,          // PSID'den ad cozulmez; ayri API cagrisi ister
          kanal: 'messenger',
          // 🔴 KORELASYON KIMLIGI (CR-002 madde 2).
          // Ajan cokerse 'continueRegularOutput' giris ogesini gecirmez;
          // hata kaydinin hangi istege ait oldugunu bu kimlik soyler.
          // 🔴 mid KULLANILMAZ - PII tasiyicisi sayilir, hata kaydina girmez.
          korelasyon: korelasyonUret('ms'),
          // 🔴 TRAFIK SINIFI GIRISTE BELIRLENIR (CR-002.5 madde A).
          trafik: trafikSinifi(gonderen),
          mesajId: mid || null,
          mesajTipi: metin ? 'text' : (ekTipi || 'bilinmiyor'),
          metinMi: Boolean(metin),
          sayfaId: sayfaId || null,
          pencereIcinde,
          damgaGecerli,
          zaman: damgaGecerli ? damga : null
        }
      });
    }
  }
}

// Elenenler SAYILIR ve kayda gecer: "hic mesaj gelmedi" ile "geldi ama
// elendi" ayri seylerdir. Bu ayrim olmadan echo dongusu sessizce buyur.
if (cikti.length === 0) {
  return [{ json: { gecerli: false, bosGecti: true, elenen } }];
}
cikti[0].json.elenen = elenen;
return cikti;

