// -----------------------------------------------------------------------------
function piiTemizle(metin) {
  let t = String(metin == null ? '' : metin);
  // e-posta
  t = t.replace(/[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/g, '<eposta>');
  // 6+ haneli rakam dizileri (telefon, wamid, sipariş no, kart benzeri)
  t = t.replace(/\d{6,}/g, '<sayi>');
